```tsx
export function LineChart({title, subtitle, labels, series, unit}: LineChartProps) {
  const n = labels.length;
  const max = Math.max(...series.flatMap(s => s.values), 0);
  const ticks = niceTicks(max);
  const top = ticks[ticks.length - 1];

  const x = (i: number) => M.left + (n > 1 ? (PLOT_W * i) / (n - 1) : PLOT_W / 2);
  const y = (v: number) => M.top + PLOT_H * (1 - v / top);

  const [active, setActive] = React.useState<number | null>(null);
  const [showTable, setShowTable] = React.useState(false);
  const plotRef = React.useRef<HTMLDivElement>(null);

  const colorOf = (i: number) => `var(--lc-series-${(i % 8) + 1})`;

  const linePath = (values: number[]) =>
    values.map((v, i) => `${i === 0 ? 'M' : 'L'}${x(i).toFixed(2)},${y(v).toFixed(2)}`).join(' ');

  // direct end labels only when the endpoints don't collide
  const ends = series.map((s, i) => ({i, y: y(s.values[n - 1])})).sort((a, b) => a.y - b.y);
  const collide = ends.some((e, k) => k > 0 && e.y - ends[k - 1].y < END_LABEL_MIN_GAP);

  const format = (v: number) => v.toLocaleString('ru-RU');
  const fmtUnit = (v: number) => (unit ? `${format(v)} ${unit}` : format(v));

  const handlePointer = (e: React.PointerEvent<SVGRectElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const rel = ((e.clientX - rect.left) / rect.width) * PLOT_W;
    const idx = Math.round((rel / PLOT_W) * (n - 1));
    setActive(Math.max(0, Math.min(n - 1, idx)));
  };

  const handleKey = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
      e.preventDefault();
      setActive((cur) => {
        const base = cur ?? (e.key === 'ArrowRight' ? -1 : n);
        return Math.max(0, Math.min(n - 1, base + (e.key === 'ArrowRight' ? 1 : -1)));
      });
    } else if (e.key === 'Home') { e.preventDefault(); setActive(0); }
    else if (e.key === 'End') { e.preventDefault(); setActive(n - 1); }
    else if (e.key === 'Escape') { setActive(null); }
  };

  const summary = `${title}. ${series.map(s => `${s.name}: от ${fmtUnit(s.values[0])} до ${fmtUnit(s.values[n-1])}`).join('; ')}`;
```

